    return '''<style>
    .rp-scan-screen{position:fixed;inset:0;width:100vw;height:100vh;min-height:100vh;margin:0;overflow:hidden;display:flex;align-items:center;justify-content:center;z-index:2147483000;background:radial-gradient(circle at 50% 40%,rgba(112,88,255,.15),transparent 30%),radial-gradient(circle at 20% 80%,rgba(65,105,225,.08),transparent 28%),#07070b;border:1px solid rgba(255,255,255,.07);border-radius:24px}.rp-scan-grid{position:absolute;inset:0;opacity:.2;background-image:linear-gradient(rgba(255,255,255,.035) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.035) 1px,transparent 1px);background-size:42px 42px;animation:rp-grid-drift 12s linear infinite}.rp-scan-content{position:relative;z-index:2;width:min(700px,88vw);max-height:92vh;overflow:auto;text-align:center;padding:2rem 0}.rp-scan-content::-webkit-scrollbar{display:none}.rp-scan-content{scrollbar-width:none}.rp-scan-brand{font-size:1.65rem;font-weight:850;letter-spacing:.24em;color:#f6f5ff}.rp-scan-kicker{margin-top:.35rem;font-size:.62rem;letter-spacing:.24em;color:rgba(190,185,255,.58)}.rp-pulse-orb{position:relative;width:142px;height:142px;margin:2.1rem auto 1.25rem;display:grid;place-items:center}.rp-pulse-core{position:relative;z-index:4;width:46px;height:46px;display:grid;place-items:center;border-radius:50%;color:#fff;background:radial-gradient(circle at 35% 30%,#c9c2ff,#7765ff 48%,#3f2fa5);box-shadow:0 0 36px rgba(116,97,255,.65);animation:rp-core-pulse 1.8s ease-in-out infinite}.rp-pulse-orb.complete .rp-pulse-core{background:radial-gradient(circle at 35% 30%,#b9ffe2,#34d399 48%,#087a55)}.rp-pulse-ring{position:absolute;inset:23px;border:1px solid rgba(139,124,255,.5);border-radius:50%;animation:rp-ring 2.4s ease-out infinite}.rp-ring-2{animation-delay:.8s}.rp-ring-3{animation-delay:1.6s}.rp-scan-title{font-size:.76rem;letter-spacing:.22em;font-weight:750;color:#f0eff8}.rp-scan-repo{margin-top:.5rem;font:.82rem ui-monospace,monospace;color:rgba(224,222,240,.56)}.rp-scan-progress{width:100%;height:4px;margin:1.5rem auto .35rem;overflow:hidden;border-radius:99px;background:rgba(255,255,255,.07)}.rp-scan-progress span{display:block;height:100%;border-radius:inherit;background:linear-gradient(90deg,#6554ff,#a397ff);box-shadow:0 0 18px rgba(111,91,255,.55);transition:width .45s ease}.rp-scan-percent{text-align:right;font:.62rem ui-monospace,monospace;color:rgba(190,185,255,.6)}.rp-scan-stage{display:flex;justify-content:center;align-items:center;gap:.55rem;min-height:22px;color:rgba(235,233,247,.86);font-size:.76rem}.rp-scan-stage i{width:6px;height:6px;border-radius:50%;background:#8d7dff;box-shadow:0 0 12px #8d7dff;animation:rp-dot 1s ease-in-out infinite}.rp-scan-detail{min-height:20px;margin-top:.35rem;color:rgba(170,165,195,.55);font-size:.65rem}.rp-scan-stats{display:flex;flex-wrap:wrap;justify-content:center;gap:.45rem;margin:1rem auto}.rp-scan-stat{padding:.36rem .55rem;border:1px solid rgba(255,255,255,.06);border-radius:999px;background:rgba(255,255,255,.025);color:rgba(215,212,230,.52);font-size:.58rem}.rp-scan-stat strong{color:#dcd8ff}.rp-scan-steps{margin:1.1rem auto 0;display:grid;grid-template-columns:repeat(2,1fr);gap:.42rem;text-align:left}.rp-scan-step{display:grid;grid-template-columns:25px 14px 1fr;align-items:center;gap:.35rem;padding:.52rem .62rem;border:1px solid rgba(255,255,255,.055);border-radius:9px;background:rgba(255,255,255,.018);color:rgba(221,219,235,.34);font-size:.57rem;letter-spacing:.06em}.rp-scan-step b{font:.56rem ui-monospace,monospace;color:rgba(151,139,255,.45)}.rp-scan-step i{font-style:normal}.rp-scan-step.done{color:rgba(221,235,229,.56);border-color:rgba(52,211,153,.12)}.rp-scan-step.done i{color:#34d399}.rp-scan-step.active{border-color:rgba(139,92,246,.3);background:rgba(139,92,246,.08);color:#e9e6ff;box-shadow:inset 2px 0 #8b5cf6}.rp-scan-terminal{margin:1rem auto 0;padding:.65rem .85rem;text-align:left;border:1px solid rgba(255,255,255,.05);border-radius:10px;background:rgba(0,0,0,.22);font:.59rem/1.55 ui-monospace,monospace;color:rgba(170,165,195,.44)}@keyframes rp-ring{0%{transform:scale(.65);opacity:.8}80%,100%{transform:scale(1.55);opacity:0}}@keyframes rp-core-pulse{0%,100%{transform:scale(.94)}50%{transform:scale(1.08)}}@keyframes rp-dot{0%,100%{opacity:.35;transform:scale(.8)}50%{opacity:1;transform:scale(1.15)}}@keyframes rp-grid-drift{from{transform:translate(0,0)}to{transform:translate(42px,42px)}}@media(max-width:700px){.rp-scan-screen{min-height:84vh}.rp-scan-steps{grid-template-columns:1fr}.rp-scan-stats{display:none}}@media(prefers-reduced-motion:reduce){.rp-scan-grid,.rp-pulse-core,.rp-pulse-ring,.rp-scan-stage i{animation:none!important}.rp-scan-progress span{transition:none!important}}
    </style>'''
